from z3 import *

# Create a Z3 solver
solver = Solver()

# Variables
E = [[Bool(f"E_{i}_{j}") if i < j else None for j in range(12)] for i in range(12)]
C = [Int(f"C_{i}") for i in range(12)]

# Known edges
known_edges = [(0,10), (0,11), (0,7), (3,10), (2,9), (1,9), (3,6)]
for u, v in known_edges:
    if u > v:
        u, v = v, u
    solver.add(E[u][v] == True)

# Degree >= 4
for i in range(12):
    deg = []
    for j in range(12):
        if i < j:
            deg.append(If(E[i][j], 1, 0))
        elif i > j:
            deg.append(If(E[j][i], 1, 0))
    solver.add(Sum(deg) >= 4)

# Chromatic number <= 5
for i in range(12):
    solver.add(C[i] >= 0, C[i] <= 4)

for i in range(12):
    for j in range(i + 1, 12):
        solver.add(Implies(E[i][j], C[i] != C[j]))

# Max clique size <= 4 (no clique of size 5)
import itertools
for combo in itertools.combinations(range(12), 5):
    # At least one edge must be missing
    missing_edge = []
    for u, v in itertools.combinations(combo, 2):
        if u > v:
            u, v = v, u
        missing_edge.append(Not(E[u][v]))
    solver.add(Or(missing_edge))

# Solve
if solver.check() == sat:
    m = solver.model()
    edges = []
    for i in range(12):
        for j in range(i + 1, 12):
            if is_true(m[E[i][j]]):
                edges.append((i, j))
    print("SAT")
    print(edges)
else:
    print("UNSAT")
